<template><div class="app"><aside class="sidebar"><div class="brand"><img src="/infravault-logo.svg" alt="" class="brand-logo"> <span>InfraVault</span></div><NuxtLink class="nav" to="/">Dashboard</NuxtLink><NuxtLink class="nav" to="/racks">Visual Racks</NuxtLink><NuxtLink class="nav" to="/devices">Device Inventory</NuxtLink><NuxtLink class="nav" to="/connections">Patch Connections</NuxtLink><div v-if="user?.is_super_admin" class="admin-menu"><button type="button" class="nav admin-toggle" :aria-expanded="adminOpen" aria-controls="admin-submenu" @click="adminOpen = !adminOpen"><span>Administration</span><span class="admin-chevron" :class="{ expanded: adminOpen }">›</span></button><div v-if="adminOpen" id="admin-submenu" class="admin-submenu" role="menu"><NuxtLink class="nav admin-link" to="/admin/users">Users</NuxtLink><NuxtLink class="nav admin-link" to="/admin/companies">Companies</NuxtLink><NuxtLink class="nav admin-link" to="/admin/company-access">Company Access</NuxtLink></div></div><div class="muted" style="margin-top:35px">{{user?.display_name}} · {{user?.role}}</div><button style="margin-top:10px" @click="logout">Sign out</button></aside><main class="main"><slot /></main></div></template><script setup lang="ts">const user=useAuth();const route=useRoute();const adminOpen=ref(route.path.startsWith('/admin'));watch(()=>route.path,(path)=>{if(path.startsWith('/admin'))adminOpen.value=true});async function logout(){await $fetch('/api/auth/logout',{method:'POST'});user.value=null;await navigateTo('/login')}</script>

